(()=>{const steps=[["FACE DETECTION","얼굴 영역을 감지하고 있어요","정면 얼굴과 분석 가능한 영역을 확인하고 있어요"],["LANDMARK MAPPING","얼굴의 주요 특징점을 분석하고 있어요","눈 · 코 · 입 · 윤곽의 위치 관계를 정리하고 있어요"],["FEATURE EXTRACTION","얼굴 특징을 벡터로 변환하고 있어요","형태와 비율 정보를 비교 가능한 특징으로 변환하고 있어요"],["SIMILARITY SEARCH","수많은 후보와 유사도를 비교하고 있어요","데이터셋 전체에서 가까운 후보를 빠르게 좁히고 있어요"],["TOP MATCH SELECTION","가장 닮은 인물을 선별하고 있어요","유사도가 높은 후보를 다시 비교해 TOP 3를 준비하고 있어요"]],durations=[1400,1600,1500,2200,1500];let timer=null,active=null;function render(el){if(el.dataset.analysisEnhanced)return;el.dataset.analysisEnhanced="1";active=el;el.innerHTML='<div class="ai-analysis-card"><div class="ai-analysis-head"><span>AI FACE ANALYSIS</span><b class="ai-step-count">01 / 05</b></div><div class="ai-scan"><div class="ai-face-grid"><i></i><i></i><i></i><i></i><span class="ai-scan-line"></span><span class="ai-face-mark m1"></span><span class="ai-face-mark m2"></span><span class="ai-face-mark m3"></span><span class="ai-face-mark m4"></span><span class="ai-face-mark m5"></span></div></div><div class="ai-stage"><small class="ai-code"></small><strong class="ai-title"></strong><p class="ai-desc"></p></div><div class="ai-progress"><span></span></div><div class="ai-foot"><span class="ai-status">ANALYZING</span><span class="ai-percent">0%</span></div></div>';let index=0,elapsed=0,total=durations.reduce((a,b)=>a+b,0);function show(){if(!document.body.contains(el)){clearTimeout(timer);return}const s=steps[index];el.querySelector(".ai-code").textContent=s[0];el.querySelector(".ai-title").textContent=s[1];el.querySelector(".ai-desc").textContent=s[2];el.querySelector(".ai-step-count").textContent=String(index+1).padStart(2,"0")+" / 05";const pct=Math.min(96,Math.round(((elapsed+durations[index]*.72)/total)*100));el.querySelector(".ai-progress span").style.width=pct+"%";el.querySelector(".ai-percent").textContent=pct+"%";timer=setTimeout(()=>{elapsed+=durations[index];if(index<steps.length-1){index++;show()}else{el.querySelector(".ai-progress span").style.width="98%";el.querySelector(".ai-percent").textContent="98%";el.querySelector(".ai-status").textContent="FINALIZING"}},durations[index])}show()}new MutationObserver(()=>{const el=document.querySelector(".loading-overlay");if(el&&el!==active)render(el);if(!el)active=null}).observe(document.documentElement,{childList:true,subtree:true});})();